from pathlib import Path

def replace(file, old, new):
    p=Path('report')/file
    s=p.read_text(encoding='utf-8')
    assert old in s, (file,old)
    p.write_text(s.replace(old,new),encoding='utf-8')

replace('models.tex','Cancelled, Expired, and Delivered are persistent business states.', 'Cancelled, Expired, Delivered, and DeliveryFailed are persistent business states.')
